const item = $json.body || $json;
const slug = item.slug || '2026-10-03-beispiel';
const audioPath = item.audio_path || `/workspace/blog/public/audio/articles/${slug}.mp3`;
const articlePath = item.article_path || `/workspace/blog/content/posts/${slug}/index.md`;

return [{
  json: {
    slug,
    audioPath,
    articlePath
  }
}];

let result = {};
try {
  result = JSON.parse($json.stdout || '{}');
} catch (e) {
  result = { status: 'parse_error', error: e.message, passed: false };
}

return [{
  json: {
    passed: result.passed === true,
    score: result.similarity_score || 0.0,
    status: result.status || 'unknown',
    timestamp: new Date().toISOString()
  }
}];
